// Device Redirect Script - redirect based on device type
(function() {
    var trackerUrl = '${qt}';
    var campaignId = 'YOUR_CAMPAIGN_ID';
    
    var mobileUrl = 'https://mobile-offer.com';
    var desktopUrl = 'https://desktop-offer.com';
    var tabletUrl = 'https://tablet-offer.com';
    
    function getDeviceType() {
        var ua = navigator.userAgent;
        if (/tablet|ipad/i.test(ua)) return 'tablet';
        if (/mobile|iphone|ipod|android|blackberry|opera mini|iemobile/i.test(ua)) return 'mobile';
        return 'desktop';
    }
    
    var device = getDeviceType();
    var targetUrl = device === 'mobile' ? mobileUrl : 
                    device === 'tablet' ? tabletUrl : desktopUrl;
    
    // Track click and redirect
    var clickUrl = trackerUrl + '/click.php?campaign_id=' + campaignId + 
        '&sub1=' + device + '&redirect=0';
    
    fetch(clickUrl).finally(() => {
        window.location.href = targetUrl;
    });
})();
